/*
	   注：加载可能慢，偶尔会宕机。

//简繁
简体?language=zh_cn  繁体&language=zh_tw
//分类
type=[["热门","hot"],["口碑","score"],["新书","new"],["完结","end"]];
*/

source.exploreUrl:
@js:
sort=[];
push=(title,url,type1,type2)=>sort.push({
		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});

	bd = [["人气","hot"],["好评","score"],["推荐","last"],["完结","end"],["新书","new"]];

	   	[["男频","0"],["女频","1"]].map([title,gender]=>{
	push(title+"❤榜单", null, 1, 1);
	  bd.map(([title,uri],index)=>{
	    url= `/paihang/liebiao?rankid=${uri}&gender=${gender}`;
	if(index+1 <= bd.length - bd.length%3)
			 {	push(title, url, 1, 0.25);}
				else{ push(title, url, 0, 0.29);}
   });  
	});


	fl=[
  ["男频","0",
[["玄幻",["东方玄幻","异界大陆","异界争霸","远古神话"]],
["奇幻",["西方奇幻","领主贵族","亡灵异族","魔法校园"]],
["武侠",["传统武侠","新派武侠","国术武侠"]],
["仙侠",["古典仙侠","幻想修仙","现代修仙","洪荒封神"]],
["都市",["都市生活","爱情婚姻","异术超能","恩怨情仇","青春校园","现实百态"]],["生活",["娱乐明星","官场沉浮","商场职场"]],
["职场",["娱乐明星","官场沉浮","职场百态","商场职场"]],
["历史",["穿越历史","架空历史","历史传记"]],
["军事",["军事战争","战争幻想","谍战特工","军旅生涯","抗战烽火"]],
["游戏",["游戏生涯","电子竞技","虚拟网游","游戏异界"]],
["竞技",["体育竞技","篮球运动","足球运动","棋牌桌游"]],
["科幻",["星际战争","时空穿梭","未来世界","古武机甲","超级科技","进化变异","末世危机"]],
["灵异",["推理侦探","恐怖惊悚","寻墓探险","灵异奇谈"]],
["同人",["武侠同人","影视同人","动漫同人","游戏同人","小说同人"]],
["轻小说",["轻小说","二次元"]],
["其他",[""]]]],

  ["女频","1",
[["玄幻奇幻",["玄幻异世","奇幻魔法"]],["武侠仙侠",["武侠","仙侠"]],
["游戏竞技",[""]],
["悬疑灵异",["悬疑","灵异"]],
["古代言情",["穿越时空","古代历史","古典架空","宫闱宅斗","经商种田"]],
["现代言情",["豪门总裁","都市生活","婚恋情感","商战职场","异术超能"]],
["青春校园",[""]],
["耽美",["古代耽美","现代耽美"]],
["科幻",[""]],
["同人",["小说同人","动漫同人","影视同人","游戏同人"]],
["女尊",[""]],["莉莉",[""]],["其他",[""]]]]
];


fl.map([title,gender,list]=>{
      	push(title+"❤分类",null,1,1);			
		list.map([major,list]=>{			      	
			 push("🍁"+major+"🍁",null,1,1);
	   list.map((minor,index)=>{ 
	   text = minor!=""?minor:"全部"; 
	   url=`/fenlei/liebiao?gender=${gender}&type=hot&major=${major}&minor=${minor}&start={{(page-1)*20}}&limit=20`;     
	   	   	if(index +1<= list.length - list.length%2)
			 {	push(text, url,1, 0.4); }
				else{ push(text, url,0, 0.4); }

	});
	});	
	});



JSON.stringify(sort);

