function getUrl(url,cook){
	url = /^http/.test(url)?url:"http://www.txtnovel.vip/"+url;
	uu = java.get(url,{"Cookie":cook});
	if(/filename/.test(uu.header("Content-Disposition"))){
		uu = url;
